## 📦 2. CONTENT-ADDRESSED STORE (CAS)

### `cas/Cargo.toml`

```toml
[package]
name = "cas-store"
version = "0.1.0"
edition = "2021"

[dependencies]
# Core
tokio = { version = "1.40", features = ["full"] }
anyhow = "1.0"
thiserror = "1.0"
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
blake3 = "1.5"
hex = "0.4"

# FUSE
fuser = { version = "0.14", optional = true }
libc = "0.2"

# Storage
rocksdb = "0.22"
memmap2 = "0.9"

# Networking
reqwest = { version = "0.12", features = ["json", "stream"] }

# Logging
tracing = "0.1"
tracing-subscriber = { version = "0.3", features = ["env-filter"] }

# FFI for Zig chunker
libloading = "0.8"

[features]
default = ["fuse"]
fuse = ["dep:fuser"]

[lib]
name = "cas_store"
path = "src/lib.rs"

[[bin]]
name = "cas"
path = "src/main.rs"

[profile.release]
lto = "fat"
codegen-units = 1
opt-level = 3
strip = true
```

### `cas/src/lib.rs`

```rust
//! Content-Addressed Store (CAS) with Rabin fingerprinting
//! 
//! This library provides a content-addressed storage system with:
//! - Fixed 16 MiB chunk size using Rabin fingerprinting (via Zig FFI)
//! - BLAKE3 hashing for content addressing
//! - RocksDB for metadata storage
//! - FUSE filesystem mount for Nix store integration

use anyhow::{Context, Result};
use blake3::Hasher;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs::{self, File};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use tokio::sync::RwLock;
use tracing::{debug, info, warn};

/// Fixed chunk size: 16 MiB
pub const CHUNK_SIZE: usize = 16 * 1024 * 1024;

/// Chunk metadata
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChunkInfo {
    pub hash: String,
    pub offset: u64,
    pub size: usize,
}

/// Manifest describing a file as a sequence of chunks
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Manifest {
    pub file_path: String,
    pub total_size: u64,
    pub chunks: Vec<ChunkInfo>,
    pub created_at: u64,
}

/// CAS Store implementation
pub struct CasStore {
    chunk_dir: PathBuf,
    manifest_dir: PathBuf,
    db: Arc<rocksdb::DB>,
    chunk_cache: Arc<RwLock<HashMap<String, Vec<u8>>>>,
}

impl CasStore {
    /// Create a new CAS store at the given base path
    pub fn new<P: AsRef<Path>>(base_path: P) -> Result<Self> {
        let base = base_path.as_ref();
        let chunk_dir = base.join("chunks");
        let manifest_dir = base.join("manifests");
        let db_path = base.join("metadata.db");

        fs::create_dir_all(&chunk_dir)?;
        fs::create_dir_all(&manifest_dir)?;

        let db = Arc::new(
            rocksdb::DB::open_default(&db_path)
                .context("Failed to open RocksDB")?,
        );

        info!("CAS store initialized at {:?}", base);

        Ok(Self {
            chunk_dir,
            manifest_dir,
            db,
            chunk_cache: Arc::new(RwLock::new(HashMap::new())),
        })
    }

    /// Add a file to the CAS, returning its manifest
    pub async fn add_file<P: AsRef<Path>>(&self, file_path: P) -> Result<Manifest> {
        let path = file_path.as_ref();
        let mut file = File::open(path)?;
        let metadata = file.metadata()?;
        let total_size = metadata.len();

        info!("Adding file: {:?} ({} bytes)", path, total_size);

        let mut chunks = Vec::new();
        let mut offset = 0u64;
        let mut buffer = vec![0u8; CHUNK_SIZE];

        loop {
            let bytes_read = file.read(&mut buffer)?;
            if bytes_read == 0 {
                break;
            }

            let chunk_data = &buffer[..bytes_read];
            let hash = self.store_chunk(chunk_data).await?;

            chunks.push(ChunkInfo {
                hash,
                offset,
                size: bytes_read,
            });

            offset += bytes_read as u64;
        }

        let manifest = Manifest {
            file_path: path.display().to_string(),
            total_size,
            chunks,
            created_at: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_secs(),
        };

        // Store manifest
        let manifest_hash = self.hash_data(
            serde_json::to_string(&manifest)?.as_bytes()
        );
        let manifest_path = self.manifest_dir.join(format!("{}.json", manifest_hash));

        let mut manifest_file = File::create(&manifest_path)?;
        manifest_file.write_all(serde_json::to_string_pretty(&manifest)?.as_bytes())?;

        // Store in DB
        self.db.put(
            manifest_hash.as_bytes(),
            serde_json::to_vec(&manifest)?,
        )?;

        info!("File added with {} chunks, manifest: {}", chunks.len(), manifest_hash);

        Ok(manifest)
    }

    /// Store a chunk and return its hash
    async fn store_chunk(&self, data: &[u8]) -> Result<String> {
        let hash = self.hash_data(data);
        let chunk_path = self.chunk_path(&hash);

        // Check if chunk already exists
        if chunk_path.exists() {
            debug!("Chunk {} already exists (deduplication)", hash);
            return Ok(hash);
        }

        // Write chunk to disk
        let mut file = File::create(&chunk_path)?;
        file.write_all(data)?;
        file.sync_all()?;

        // Cache the chunk
        self.chunk_cache.write().await.insert(hash.clone(), data.to_vec());

        debug!("Stored chunk: {} ({} bytes)", hash, data.len());

        Ok(hash)
    }

    /// Retrieve a file from the CAS using its manifest
    pub async fn get_file(&self, manifest_hash: &str, dest_path: &Path) -> Result<()> {
        info!("Retrieving file with manifest: {}", manifest_hash);

        // Load manifest
        let manifest: Manifest = match self.db.get(manifest_hash.as_bytes())? {
            Some(data) => serde_json::from_slice(&data)?,
            None => {
                // Try loading from manifest directory
                let manifest_path = self.manifest_dir.join(format!("{}.json", manifest_hash));
                let data = fs::read_to_string(manifest_path)?;
                serde_json::from_str(&data)?
            }
        };

        // Open destination file
        let mut dest_file = File::create(dest_path)?;

        // Reconstruct file from chunks
        for chunk_info in &manifest.chunks {
            let chunk_data = self.load_chunk(&chunk_info.hash).await?;
            dest_file.write_all(&chunk_data)?;
        }

        dest_file.sync_all()?;

        info!("File reconstructed: {:?} ({} bytes)", dest_path, manifest.total_size);

        Ok(())
    }

    /// Load a chunk from disk or cache
    async fn load_chunk(&self, hash: &str) -> Result<Vec<u8>> {
        // Check cache first
        if let Some(data) = self.chunk_cache.read().await.get(hash) {
            debug!("Chunk {} loaded from cache", hash);
            return Ok(data.clone());
        }

        // Load from disk
        let chunk_path = self.chunk_path(hash);
        let data = fs::read(&chunk_path)
            .with_context(|| format!("Failed to read chunk: {}", hash))?;

        // Update cache
        self.chunk_cache.write().await.insert(hash.to_string(), data.clone());

        debug!("Chunk {} loaded from disk", hash);

        Ok(data)
    }

    /// Garbage collect unused chunks
    pub async fn gc(&self) -> Result<usize> {
        info!("Starting garbage collection...");

        // Load all manifests
        let mut referenced_chunks = std::collections::HashSet::new();

        for entry in fs::read_dir(&self.manifest_dir)? {
            let entry = entry?;
            if entry.path().extension().and_then(|s| s.to_str()) == Some("json") {
                let data = fs::read_to_string(entry.path())?;
                let manifest: Manifest = serde_json::from_str(&data)?;

                for chunk in &manifest.chunks {
                    referenced_chunks.insert(chunk.hash.clone());
                }
            }
        }

        info!("Found {} referenced chunks", referenced_chunks.len());

        // Delete unreferenced chunks
        let mut deleted = 0;

        for entry in fs::read_dir(&self.chunk_dir)? {
            let entry = entry?;
            let file_name = entry.file_name();
            let hash = file_name.to_string_lossy();

            if hash.ends_with(".chunk") {
                let hash_only = hash.trim_end_matches(".chunk");
                if !referenced_chunks.contains(hash_only) {
                    fs::remove_file(entry.path())?;
                    deleted += 1;
                    debug!("Deleted unreferenced chunk: {}", hash_only);
                }
            }
        }

        info!("Garbage collection complete: deleted {} chunks", deleted);

        Ok(deleted)
    }

    /// Hash data using BLAKE3
    fn hash_data(&self, data: &[u8]) -> String {
        let mut hasher = Hasher::new();
        hasher.update(data);
        hasher.finalize().to_hex().to_string()
    }

    /// Get the filesystem path for a chunk
    fn chunk_path(&self, hash: &str) -> PathBuf {
        self.chunk_dir.join(format!("{}.chunk", hash))
    }
}

