//! Rabin fingerprinting chunker (16 MiB fixed-size chunks)
//! 
//! This module implements content-defined chunking using Rabin fingerprinting
//! with a fixed chunk size of 16 MiB for predictable memory usage.

const std = @import("std");
const mem = std.mem;
const crypto = std.crypto;

/// Fixed chunk size: 16 MiB
pub const CHUNK_SIZE: usize = 16 * 1024 * 1024;

/// Rabin polynomial parameters
const POLYNOMIAL: u64 = 0x3DA3358B4DC173;
const WINDOW_SIZE: usize = 64;

/// Chunk metadata
pub const ChunkInfo = struct {
    hash: [32]u8,
    offset: u64,
    size: usize,
};

/// Rabin fingerprint state
const RabinState = struct {
    window: [WINDOW_SIZE]u8,
    window_pos: usize,
    fingerprint: u64,
    poly_pow: u64,

    pub fn init() RabinState {
        var state = RabinState{
            .window = undefined,
            .window_pos = 0,
            .fingerprint = 0,
            .poly_pow = 1,
        };

        // Initialize window with zeros
        @memset(&state.window, 0);

        // Precompute polynomial power
        var i: usize = 0;
        while (i < WINDOW_SIZE) : (i += 1) {
            state.poly_pow = polyMul(state.poly_pow, POLYNOMIAL);
        }

        return state;
    }

    pub fn roll(self: *RabinState, byte: u8) void {
        const old_byte = self.window[self.window_pos];
        self.window[self.window_pos] = byte;
        self.window_pos = (self.window_pos + 1) % WINDOW_SIZE;

        // Update fingerprint: remove old byte, add new byte
        const old_contribution = polyMul(@as(u64, old_byte), self.poly_pow);
        self.fingerprint = polyMul(self.fingerprint, POLYNOMIAL) ^ old_contribution ^ @as(u64, byte);
    }

    fn polyMul(a: u64, b: u64) u64 {
        return a *% b;
    }
};

/// Chunker state machine
pub const Chunker = struct {
    allocator: mem.Allocator,
    rabin: RabinState,
    buffer: std.ArrayList(u8),
    chunks: std.ArrayList(ChunkInfo),
    current_offset: u64,

    pub fn init(allocator: mem.Allocator) Chunker {
        return Chunker{
            .allocator = allocator,
            .rabin = RabinState.init(),
            .buffer = std.ArrayList(u8).init(allocator),
            .chunks = std.ArrayList(ChunkInfo).init(allocator),
            .current_offset = 0,
        };
    }

    pub fn deinit(self: *Chunker) void {
        self.buffer.deinit();
        self.chunks.deinit();
    }

    /// Process data and generate chunks
    pub fn process(self: *Chunker, data: []const u8) !void {
        for (data) |byte| {
            try self.buffer.append(byte);
            self.rabin.roll(byte);

            // Create chunk when reaching CHUNK_SIZE or at boundary
            if (self.buffer.items.len >= CHUNK_SIZE) {
                try self.createChunk();
            }
        }
    }

    /// Finalize and create last chunk if needed
    pub fn finalize(self: *Chunker) !void {
        if (self.buffer.items.len > 0) {
            try self.createChunk();
        }
    }

    fn createChunk(self: *Chunker) !void {
        const chunk_data = self.buffer.items;
        const chunk_size = chunk_data.len;

        // Compute BLAKE3 hash
        var hash: [32]u8 = undefined;
        crypto.hash.Blake3.hash(chunk_data, &hash, .{});

        // Store chunk info
        try self.chunks.append(ChunkInfo{
            .hash = hash,
            .offset = self.current_offset,
            .size = chunk_size,
        });

        self.current_offset += chunk_size;
        self.buffer.clearRetainingCapacity();
    }

    pub fn getChunks(self: *const Chunker) []const ChunkInfo {
        return self.chunks.items;
    }
};

/// C FFI exports for use from other languages

export fn chunker_new() ?*Chunker {
    const allocator = std.heap.c_allocator;
    const chunker = allocator.create(Chunker) catch return null;
    chunker.* = Chunker.init(allocator);
    return chunker;
}

export fn chunker_free(chunker: *Chunker) void {
    const allocator = std.heap.c_allocator;
    chunker.deinit();
    allocator.destroy(chunker);
}

export fn chunker_process(chunker: *Chunker, data: [*]const u8, len: usize) c_int {
    const slice = data[0..len];
    chunker.process(slice) catch return -1;
    return 0;
}

export fn chunker_finalize(chunker: *Chunker) c_int {
    chunker.finalize() catch return -1;
    return 0;
}

export fn chunker_get_chunks(chunker: *const Chunker, out_len: *usize) [*]const ChunkInfo {
    const chunks = chunker.getChunks();
    out_len.* = chunks.len;
    return chunks.ptr;
}

// Tests
test "chunker basic functionality" {
    var chunker = Chunker.init(std.testing.allocator);
    defer chunker.deinit();

    // Create test data (20 MB)
    const test_size = 20 * 1024 * 1024;
    const data = try std.testing.allocator.alloc(u8, test_size);
    defer std.testing.allocator.free(data);

    // Fill with deterministic pattern
    for (data, 0..) |*byte, i| {
        byte.* = @intCast(i % 256);
    }

    // Process
    try chunker.process(data);
    try chunker.finalize();

    // Verify chunks
    const chunks = chunker.getChunks();
    try std.testing.expect(chunks.len > 0);

    // Should create at least 1 chunk (20MB / 16MB = 1.25 chunks)
    try std.testing.expect(chunks.len >= 1);
}

test "chunker deduplication" {
    var chunker1 = Chunker.init(std.testing.allocator);
    defer chunker1.deinit();

    var chunker2 = Chunker.init(std.testing.allocator);
    defer chunker2.deinit();

    const data = "Hello, World!".* ** 1000;

    try chunker1.process(&data);
    try chunker1.finalize();

    try chunker2.process(&data);
    try chunker2.finalize();

    const chunks1 = chunker1.getChunks();
    const chunks2 = chunker2.getChunks();

    try std.testing.expectEqual(chunks1.len, chunks2.len);

    for (chunks1, chunks2) |c1, c2| {
        try std.testing.expectEqualSlices(u8, &c1.hash, &c2.hash);
    }
}
