```nim
## Snapshot Engine Daemon
## 
## Provides JSON-RPC interface for immutable snapshot management with
## copy-on-write semantics. Integrates with Zig chunker and Rust manifest.

import std/[asyncdispatch, asyncnet, json, tables, times, os, strutils, strformat]
import std/locks

# FFI imports for Zig chunker
{.passL: "-L. -lchunker".}

type
  ChunkInfo {.importc, header: "chunker.h".} = object
    hash: array[32, uint8]
    offset: uint64
    size: uint

  Chunker {.importc, header: "chunker.h".} = object

proc chunker_new(): ptr Chunker {.importc.}
proc chunker_free(c: ptr Chunker) {.importc.}
proc chunker_process(c: ptr Chunker, data: ptr uint8, len: uint): cint {.importc.}
proc chunker_finalize(c: ptr Chunker): cint {.importc.}
proc chunker_get_chunks(c: ptr Chunker, outLen: ptr uint): ptr UncheckedArray[ChunkInfo] {.importc.}

# Snapshot types
type
  SnapshotId = string

  FileEntry = object
    path: string
    chunks: seq[ChunkInfo]
    size: uint64
    modified: int64

  SnapshotManifest = object
    id: SnapshotId
    baseId: Option[SnapshotId]
    files: Table[string, FileEntry]
    created: int64
    committed: bool

  SnapshotStore = ref object
    basePath: string
    snapshots: Table[SnapshotId, SnapshotManifest]
    lock: Lock

# Global snapshot store
var store: SnapshotStore

proc initStore(basePath: string): SnapshotStore =
  result = SnapshotStore(
    basePath: basePath,
    snapshots: initTable,
  )
  initLock(result.lock)
  createDir(basePath / "manifests")
  createDir(basePath / "chunks")

proc generateId(): SnapshotId =
  ## Generate unique snapshot ID
  &"snap_{getTime().toUnix}_{rand(100000)}"

proc hashToHex(hash: array[32, uint8]): string =
  result = ""
  for b in hash:
    result.add(&"{b:02x}")

proc fork(store: SnapshotStore, baseId: SnapshotId): SnapshotId =
  ## Fork a snapshot (copy-on-write)
  acquire(store.lock)
  defer: release(store.lock)

  let newId = generateId()

  if baseId in store.snapshots:
    let base = store.snapshots[baseId]
    var newManifest = SnapshotManifest(
      id: newId,
      baseId: some(baseId),
      files: base.files,  # Shallow copy - COW
      created: getTime().toUnix,
      committed: false
    )
    store.snapshots[newId] = newManifest
  else:
    # Create new empty snapshot
    var newManifest = SnapshotManifest(
      id: newId,
      baseId: none(SnapshotId),
      files: initTable,
      created: getTime().toUnix,
      committed: false
    )
    store.snapshots[newId] = newManifest

  echo &"Forked snapshot {baseId} -> {newId}"
  return newId

proc write(store: SnapshotStore, snapshotId: SnapshotId, path: string, data: string) =
  ## Write data to a file in snapshot (COW)
  acquire(store.lock)
  defer: release(store.lock)

  if snapshotId notin store.snapshots:
    raise newException(ValueError, &"Snapshot {snapshotId} not found")

  var manifest = store.snapshots[snapshotId]
  if manifest.committed:
    raise newException(ValueError, &"Snapshot {snapshotId} is committed (immutable)")

  # Chunk the data using Zig chunker
  let chunker = chunker_new()
  defer: chunker_free(chunker)

  discard chunker_process(chunker, cast[ptr uint8](data[0].unsafeAddr), data.len.uint)
  discard chunker_finalize(chunker)

  var chunkCount: uint
  let chunks = chunker_get_chunks(chunker, chunkCount.addr)

  # Store chunks to disk
  var fileChunks = newSeq
  for i in 0..<chunkCount:
    let chunk = chunks[i]
    let hash = hashToHex(chunk.hash)
    let chunkPath = store.basePath / "chunks" / &"{hash}.chunk"

    # Write chunk if it doesn't exist (deduplication)
    if not fileExists(chunkPath):
      let chunkData = data.substr(chunk.offset.int, chunk.offset.int + chunk.size.int - 1)
      writeFile(chunkPath, chunkData)

    fileChunks.add(chunk)

  # Update manifest
  let entry = FileEntry(
    path: path,
    chunks: fileChunks,
    size: data.len.uint64,
    modified: getTime().toUnix
  )
  manifest.files[path] = entry
  store.snapshots[snapshotId] = manifest

  echo &"Wrote {data.len} bytes to {path} in snapshot {snapshotId} ({chunkCount} chunks)"

proc read(store: SnapshotStore, snapshotId: SnapshotId, path: string): string =
  ## Read data from a file in snapshot
  acquire(store.lock)
  defer: release(store.lock)

  if snapshotId notin store.snapshots:
    raise newException(ValueError, &"Snapshot {snapshotId} not found")

  let manifest = store.snapshots[snapshotId]

  if path notin manifest.files:
    raise newException(ValueError, &"File {path} not found in snapshot {snapshotId}")

  let entry = manifest.files[path]
  var data = ""

  # Reconstruct file from chunks
  for chunk in entry.chunks:
    let hash = hashToHex(chunk.hash)
    let chunkPath = store.basePath / "chunks" / &"{hash}.chunk"
    let chunkData = readFile(chunkPath)
    data.add(chunkData)

  echo &"Read {data.len} bytes from {path} in snapshot {snapshotId}"
  return data

proc commit(store: SnapshotStore, snapshotId: SnapshotId): SnapshotId =
  ## Commit snapshot (make immutable)
  acquire(store.lock)
  defer: release(store.lock)

  if snapshotId notin store.snapshots:
    raise newException(ValueError, &"Snapshot {snapshotId} not found")

  var manifest = store.snapshots[snapshotId]
  manifest.committed = true
  store.snapshots[snapshotId] = manifest

  # Persist manifest to disk
  let manifestPath = store.basePath / "manifests" / &"{snapshotId}.json"
  writeFile(manifestPath, $(%manifest))

  echo &"Committed snapshot {snapshotId}"
  return snapshotId

# JSON-RPC server
proc handleRequest(store: SnapshotStore, request: JsonNode): JsonNode =
  try:
    let meth = request["method"].getStr
    let params = request["params"]
    let id = request["id"]

    case meth
    of "fork":
      let baseId = params["baseSnapshotId"].getStr
      let newId = store.fork(baseId)
      result = %*{"jsonrpc": "2.0", "id": id, "result": newId}

    of "write":
      let snapshotId = params["snapshotId"].getStr
      let path = params["path"].getStr
      let data = params["data"].getStr
      store.write(snapshotId, path, data)
      result = %*{"jsonrpc": "2.0", "id": id, "result": "ok"}

    of "read":
      let snapshotId = params["snapshotId"].getStr
      let path = params["path"].getStr
      let data = store.read(snapshotId, path)
      result = %*{"jsonrpc": "2.0", "id": id, "result": data}

    of "commit":
      let snapshotId = params["snapshotId"].getStr
      let commitId = store.commit(snapshotId)
      result = %*{"jsonrpc": "2.0", "id": id, "result": commitId}

    else:
      result = %*{
        "jsonrpc": "2.0",
        "id": id,
        "error": {"code": -32601, "message": "Method not found"}
      }

  except Exception as e:
    result = %*{
      "jsonrpc": "2.0",
      "id": request{"id"},
      "error": {"code": -32603, "message": e.msg}
    }

proc handleClient(store: SnapshotStore, client: AsyncSocket) {.async.} =
  try:
    while true:
      let line = await client.recvLine()
      if line.len == 0:
        break

      let request = parseJson(line)
      let response = store.handleRequest(request)
      await client.send($response & "\n")
  except:
    discard
  finally:
    client.close()

proc serve(store: SnapshotStore, port: int) {.async.} =
  var server = newAsyncSocket()
  server.setSockOpt(OptReuseAddr, true)
  server.bindAddr(Port(port))
  server.listen()

