```nim
## DTG Classifier - Lightweight ONNX inference
##
## Analyzes build logs/stderr to provide decision-time guidance

import std/[json, os, strutils, times, httpclient]
import onnxruntime

# ONNX model loading
let modelPath = "model/classifier.onnx"
var session: OrtSession

proc initModel() =
  let env = newOrtEnv()
  let sessionOptions = newOrtSessionOptions()
  sessionOptions.setGraphOptimizationLevel(GraphOptimizationLevel.ORT_ENABLE_ALL)

  session = newOrtSession(env, modelPath, sessionOptions)
  echo "DTG Classifier loaded: ", modelPath

type
  InputData = object
    stderr: string
    log: string
    state: string  # BUILD, TEST, DEPLOY

  Guidance = enum
    NONE = 0,
    READ_LOG = 1,
    RETRY_BUILD = 2,
    SHOW_DIFF = 3,
    HALT = 4

proc classify(input: InputData): Guidance =
  ## Classify build state and return guidance

  # Tokenize input (simple implementation)
  let tokens = input.stderr.splitWhitespace & 
               input.log.splitWhitespace &
               input.state.splitWhitespace

  # Prepare input tensor (max 512 tokens, padded)
  var inputIds = newSeq
  for token in tokens[0..^1]:
    let id = token.hash mod 30522  # Mock tokenizer
    inputIds.add(id.int32)

  # Pad to 512
  while inputIds.len < 512:
    inputIds.add(0.int32)

  let inputTensor = newOrtTensor(inputIds[0..511])

  # Run inference
  let inputName = "input_ids"
  let outputName = "output"

  let outputs = session.run(inputName, outputName, inputTensor)
  let logits = outputs[0].getData[float32]

  # Softmax
  var probs = newSeq[float32](logits.len)
  var maxLogit = -float.high
  for i, logit in logits:
    if logit > maxLogit: maxLogit = logit
  var sumExp = 0.0'f32
  for logit in logits:
    sumExp += exp(logit - maxLogit)
  for i, logit in logits:
    probs[i] = exp(logit - maxLogit) / sumExp

  # Argmax
  var maxIdx = 0
  var maxProb = probs[0]
  for i in 1..<probs.len:
    if probs[i] > maxProb:
      maxProb = probs[i]
      maxIdx = i

  echo &"DTG Classification: {maxIdx} (prob: {maxProb:.3f})"
  return Guidance(maxIdx)

# HTTP server for classifier
import std/[asynchttpserver, asyncdispatch]

proc handleHttpRequest(req: Request): Future[void] {.async.} =
  if req.httpMethod == HttpPost and req.path == "/classify":
    let body = await req.body()
    let jsonData = parseJson(body)

    let input = InputData(
      stderr: jsonData["stderr"].getStr(),
      log: jsonData["log"].getStr(),
      state: jsonData["state"].getStr()
    )

    let guidance = classify(input)

    let response = %* {
      "guidance": int(guidance),
      "confidence": 0.95,  # Mock
      "timestamp": now().format("yyyy-MM-dd HH:mm:ss")
    }

    req.send(Http200, $response)
  else:
    req.send(Http404, "Not Found")

proc serveClassifier(port: int) {.async.} =
  var server = newAsyncHttpServer()
  server.listen(Port(port))

  echo &"DTG Classifier serving on localhost:{port}"
  while true:
    let (req, _) = await server.accept()
    asyncCheck handleHttpRequest(req)

when isMainModule:
  initModel()
  waitFor serveClassifier(8006)
