//! DTG Injector - Micro-instruction injection for LLM prompts

const std = @import("std");
const Guidance = enum(u32) {
    NONE = 0,
    READ_LOG = 1,
    RETRY_BUILD = 2,
    SHOW_DIFF = 3,
    HALT = 4,
};

/// Inject guidance micro-instruction into prompt
/// Returns new allocated string
pub export fn inject(prompt: [*:0]const u8, guidance: u32) ?[*:0]u8 {
    const allocator = std.heap.c_allocator;

    const g = @as(Guidance, @enumFromInt(guidance));
    const instruction = switch (g) {
        .NONE => "",
        .READ_LOG => "[[GUIDANCE: READ_LOG]]",
        .RETRY_BUILD => "[[GUIDANCE: RETRY_BUILD]]",
        .SHOW_DIFF => "[[GUIDANCE: SHOW_DIFF]]",
        .HALT => "[[GUIDANCE: HALT]]",
    };

    const prompt_len = std.mem.len(prompt);
    const instr_len = std.mem.len(instruction);
    const total_len = prompt_len + instr_len + 2; // + \n\n

    const result = allocator.alloc(u8, total_len + 1) catch return null;

    @memcpy(result[0..prompt_len], prompt[0..prompt_len]);
    result[prompt_len] = '\n';
    result[prompt_len+1] = '\n';
    @memcpy(result[prompt_len+2 .. prompt_len+2+instr_len], instruction);
    result[prompt_len+2+instr_len] = 0; // null terminator

    return @ptrCast(result.ptr);
}

test "inject guidance" {
    const allocator = std.testing.allocator;

    const prompt = "Complete this task:";
    const injected = inject(prompt, @intFromEnum(Guidance.RETRY_BUILD));
    defer allocator.free(injected.?[0 .. std.mem.len(injected.?)]);

    const expected = "Complete this task:\n\n[[GUIDANCE: RETRY_BUILD]]";
    try std.testing.expectEqualStrings(expected, injected.?);
}
