### `rag/rag/retriever.py`

```python
"""
RAG Retriever - Context retrieval for LLM planning
"""
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import List
import openai
import pinecone
from cas_store import CasStore  # From Rust FFI
import numpy as np
import os

app = FastAPI(title="RAG Service")

# Config
OPENAI_API_KEY = os.getenv("OPENAI_API_KEY")
PINECONE_API_KEY = os.getenv("PINECONE_API_KEY")
CAS_STORE_PATH = os.getenv("CAS_STORE_PATH", "/var/lib/cas")

openai.api_key = OPENAI_API_KEY
pinecone.init(api_key=PINECONE_API_KEY, environment="us-west1-gcp")
index = pinecone.Index("dev-platform-index")

cas = CasStore(CAS_STORE_PATH)

class RetrieveRequest(BaseModel):
    query: str
    top_k: int = 5

class Document(BaseModel):
    doc_id: str
    path: str
    content: str
    score: float

async def embed_text(text: str) -> List[float]:
    """Generate OpenAI embedding"""
    response = openai.Embedding.create(
        input=text,
        model="text-embedding-ada-002"
    )
    return response['data'][0]['embedding']

@app.post("/retrieve")
async def retrieve(request: RetrieveRequest) -> Dict:
    """Retrieve relevant documents for query"""
    # Embed query
    query_embedding = await embed_text(request.query)

    # Query Pinecone
    results = index.query(
        vector=query_embedding,
        top_k=request.top_k,
        include_metadata=True
    )

    documents = []

    for match in results['matches']:
        doc_id = match['id']
        metadata = match['metadata']
        score = match['score']

        # Retrieve full content from CAS
        manifest_hash = metadata['manifest_hash']
        content_path = f"/tmp/{doc_id}"

        cas.get_file(manifest_hash, content_path)
        content = open(content_path, 'r').read()[:8000]  # Truncate

        documents.append(Document(
            doc_id=doc_id,
            path=metadata['path'],
            content=content,
            score=score
        ))

    # Filter high-quality results (>0.78 cosine similarity)
    relevant = [d for d in documents if d.score > 0.78]

    return {
        "query": request.query,
        "documents": relevant,
        "relevant_count": len(relevant),
        "total_count": len(documents)
    }

@app.get("/health")
async def health():
    return {"status": "healthy", "service": "rag"}
