/* eBPF kprobe for execve auditing */
#include <linux/bpf.h>
#include <linux/ptrace.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_tracing.h>

struct event {
    __u64 timestamp;
    __u32 pid;
    __u32 uid;
    char comm[16];
    char filename[256];
    __u64 arg_count;
};

struct {
    __uint(type, BPF_MAP_TYPE_RINGBUF);
    __uint(max_entries, 256 * 1024);
} rb SEC(".maps");

SEC("kprobe/sys_execve")
int BPF_KPROBE(sys_execve, const char __user *filename, const char __user *const __user *__argv, const char __user *const __user *__envp) {
    struct event *e;
    struct task_struct *task = (struct task_struct *)bpf_get_current_task();

    e = bpf_ringbuf_reserve(&rb, sizeof(*e), 0);
    if (!e) {
        return 0;
    }

    e->timestamp = bpf_ktime_get_ns();
    e->pid = bpf_get_current_pid_tgid() >> 32;
    e->uid = bpf_get_current_uid_gid();
    bpf_get_current_comm(&e->comm, sizeof(e->comm));

    // Copy filename
    if (bpf_probe_read_user_str(e->filename, sizeof(e->filename), filename) == 0) {
        // Count argv
        e->arg_count = 0;
        const char __user *const __user *argv = __argv;
        char __user *arg;
        bpf_loop(32, ({
            bpf_probe_read_user((void *)&arg, sizeof(arg), argv + BPF_CAST(__u64, e->arg_count));
            if (!arg || bpf_probe_read_user_str(NULL, 0, arg) == 0) {
                break;
            }
            e->arg_count++;
            0;
        }));
    }

    bpf_ringbuf_submit(e, 0);
    return 0;
}

char _license[] SEC("license") = "GPL";
