const std = @import("std");
const bpf = @import("libbpf.zig");  // libbpf bindings

pub const Loader = struct {
    obj: *bpf.BpfObject,

    pub fn init(allocator: std.mem.Allocator) !Loader {
        const obj = try bpf.BpfObject.openFile("probe.o");
        try obj.load();
        return Loader{ .obj = obj };
    }

    pub fn attachExecveProbe(loader: *Loader, pid_namespace: i32) !void {
        const prog = try loader.obj.findProgramByName("sys_execve");
        const cgroup_fd = try bpf.CgroupFd.open("/sys/fs/cgroup", bpf.O_RDONLY);

        try prog.attachCgroup(cgroup_fd, bpf.BpfAttachType.KPROBE);

        // Set namespace
        if (pid_namespace != -1) {
            try bpf.setns(pid_namespace, bpf.CLONE_NEWPID);
        }
    }
};
