//! Port Authority - Dynamic port mapping service

const std = @import("std");
const net = std.net;
const mem = std.mem;

const PortPool = struct {
    allocator: mem.Allocator,
    available: std.ArrayList(u16).init(std.heap.page_allocator),
    allocated: std.AutoHashMap(u16, u32).init(std.heap.page_allocator),  // port -> workspace_id

    const Self = @This();

    pub fn init(allocator: mem.Allocator) !Self {
        var pool = Self{
            .allocator = allocator,
            .available = std.ArrayList(u16).init(allocator),
            .allocated = std.AutoHashMap(u16, u32).init(allocator),
        };

        // Initialize pool: 20000-30000
        var i: u16 = 20000;
        while (i < 30000) : (i += 1) {
            try pool.available.append(i);
        }

        return pool;
    }

    pub fn allocate(self: *Self, workspace_id: u32) ?u16 {
        if (self.available.items.len == 0) return null;

        const port = self.available.pop();
        self.allocated.put(port, workspace_id) catch return null;

        // Setup iptables DNAT
        const cmd = std.fmt.allocPrint(self.allocator, 
            "iptables -t nat -A PREROUTING -p tcp --dport {d} -j DNAT --to-destination 127.0.0.1:{}", 
            .{port, workspace_id}) catch return null;
        defer self.allocator.free(cmd);

        const result = std.ChildProcess.run(.{ .executable = "sh", .argv = &[_][]const u8{ "sh", "-c", cmd } }, 
            .{}) catch return null;

        if (result.term != .Exited or result.term.Exited != 0) {
            // Revert allocation
            _ = self.available.append(port) catch {};
            _ = self.allocated.remove(port);
            return null;
        }

        return port;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var pool = try PortPool.init(allocator);
    defer pool.available.deinit();
    defer pool.allocated.deinit();

    // gRPC-like HTTP server on port 9000
    var server = net.StreamServer.init(.{});
    defer server.deinit();
    try server.listen(net.Address.parseIp("0.0.0.0", 9000) catch unreachable);

    std.log.info("Port Authority listening on :9000", .{});

    while (true) {
        const conn = try server.accept();
        const stream = async conn.stream;

        // Parse HTTP request
        var buf: [4096]u8 = undefined;
        const n = try stream.readAll(&buf);
        const request = std.mem.trim(u8, buf[0..n], " \r\n");

        if (std.mem.startsWith(u8, request, "POST /allocate ")) {
            // Parse workspace_id from JSON body
            const body_start = std.mem.indexOf(u8, request, "{") orelse continue;
            const workspace_id = std.fmt.parseInt(u32, request[body_start..], 10) catch 3000;

            if (port = pool.allocate(workspace_id)) |external_port| {
                const response = std.fmt.allocPrint(allocator, 
                    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n{{\"external_port\": %d}}\r\n", 
                    .{external_port}) catch continue;
                defer allocator.free(response);

                _ = try stream.writeAll(response);
            } else {
                _ = try stream.writeAll("HTTP/1.1 503 Service Unavailable\r\n\r\n");
            }
        }

        stream.close();
    }
}
