### `collaboration/crdt/src/yjs_like.nim`

```nim
## Yjs-like CRDT for collaborative editing (RGA)

import std/[sequtils, tables, hashes, json, locks]

type
  Operation = object
    clientId: uint64
    clock: uint32
    position: uint32
    deleteLen: uint32
    insert: string

  RgaNode = ref object
    id: uint64  # clientId << 32 | clock
    content: string
    prevId: uint64
    nextId: uint64

  CrdtDoc {.final.} = object
    nodes: Table[uint64, RgaNode]
    head: uint64
    lock: Lock

proc hash(id: uint64): Hash =
  result = hash(id.uint32)
  result = result !& hash((id shr 32).uint32)
  result = !$result

proc newCrdtDoc(): CrdtDoc =
  result = CrdtDoc(nodes: initTable)
  initLock(result.lock)

proc apply(doc: var CrdtDoc, op: Operation) =
  acquire(doc.lock)
  defer: release(doc.lock)

  let nodeId = (op.clientId shl 32) or op.clock.uint64
  let node = RgaNode(
    id: nodeId,
    content: op.insert,
    prevId: op.position.uint64,
    nextId: 0
  )

  doc.nodes[nodeId] = node

  # Link to previous node
  if node.prevId != 0 and node.prevId in doc.nodes:
    let prev = doc.nodes[node.prevId]
    prev.nextId = nodeId

  # Update head if this is the first node
  if doc.head == 0:
    doc.head = nodeId

proc merge(doc: var CrdtDoc, remoteState: JsonNode) =
  ## Merge remote CRDT state
  acquire(doc.lock)
  defer: release(doc.lock)

  for remoteNode in remoteState["nodes"].elems:
    let id = remoteNode["id"].num.uint64
    let content = remoteNode["content"].str

    if id notin doc.nodes:
      let node = RgaNode(
        id: id,
        content: content,
        prevId: remoteNode["prevId"].num.uint64,
        nextId: remoteNode["nextId"].num.uint64
      )
      doc.nodes[id] = node

proc export(doc: CrdtDoc): string =
  ## Linearize document
  acquire(doc.lock)
  defer: release(doc.lock)

  var current = doc.head
  var result = ""

  while current != 0 and current in doc.nodes:
    let node = doc.nodes[current]
    result.add(node.content)
    current = node.nextId

  return result

# C FFI for shared library
proc crdt_new(): pointer {.exportc.} =
  cast[pointer](newCrdtDoc())

proc crdt_apply(docPtr: pointer, opJson: cstring) {.exportc.} =
  let doc = cast[ptr CrdtDoc](docPtr)[]
  let op = parseJson($opJson)
  let operation = Operation(
    clientId: op["clientId"].num.uint64,
    clock: op["clock"].num.uint32,
    position: op["position"].num.uint32,
    deleteLen: op["deleteLen"].get(0).uint32,
    insert: op["insert"].get("")
  )
  doc.apply(operation)

proc crdt_merge(docPtr: pointer, remoteJson: cstring) {.exportc.} =
  let doc = cast[ptr CrdtDoc](docPtr)[]
  doc.merge(parseJson($remoteJson))

proc crdt_export(docPtr: pointer): cstring {.exportc.} =
  let doc = cast[ptr CrdtDoc](docPtr)[]
  $doc.export()

when isMainModule:
  var doc = newCrdtDoc()
  doc.apply(Operation(clientId: 1, clock: 1, position: 0, deleteLen: 0, insert: "Hello"))
  doc.apply(Operation(clientId: 2, clock: 1, position: 5, deleteLen: 0, insert: ", World"))

  echo doc.export()  # "Hello, World"
```

