```rust
//! Snapshot Manifest Manager
//!
//! Maintains a Merkle-tree manifest mapping virtual file paths to ordered
//! lists of chunk hashes + offsets. Supports both binary protobuf and
//! JSON fallback formats.  The commit operation uses renameat2(AT_REPLACE)
//! for atomic swap of the live manifest.

use anyhow::{Context, Result};
use blake3::Hasher;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs::{self, File};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};
use tracing::{debug, info};

// ─── Data types ──────────────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ChunkRef {
    /// BLAKE3 hex hash of the chunk content
    pub hash: String,
    /// Byte offset inside the virtual file
    pub offset: u64,
    /// Byte length of this chunk
    pub size: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FileNode {
    /// Ordered list of chunks that form the file
    pub chunks: Vec<ChunkRef>,
    /// Total logical file size in bytes
    pub total_size: u64,
    /// Unix mtime (seconds since epoch)
    pub mtime: u64,
    /// File mode bits (Unix octal)
    pub mode: u32,
    /// Per-file Merkle root (hash-of-chunk-hashes)
    pub merkle_root: String,
}

/// Full snapshot manifest (serialisable to JSON or binary protobuf)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SnapshotManifest {
    pub id: String,
    pub base_id: Option<String>,
    /// BTreeMap keeps keys sorted for deterministic Merkle roots
    pub files: BTreeMap<String, FileNode>,
    pub created_at: u64,
    pub committed: bool,
    /// Root hash of the entire manifest (hash-of-file-merkle-roots)
    pub manifest_root: String,
}

// ─── Merkle helpers ──────────────────────────────────────────────────────────

fn blake3_hex(data: &[u8]) -> String {
    let mut h = Hasher::new();
    h.update(data);
    h.finalize().to_hex().to_string()
}

fn compute_file_merkle(chunks: &[ChunkRef]) -> String {
    if chunks.is_empty() {
        return blake3_hex(b"empty");
    }
    let hashes: Vec<u8> = chunks
        .iter()
        .flat_map(|c| hex::decode(&c.hash).unwrap_or_default())
        .collect();
    blake3_hex(&hashes)
}

fn compute_manifest_root(files: &BTreeMap<String, FileNode>) -> String {
    let combined: Vec<u8> = files
        .iter()
        .flat_map(|(path, node)| {
            let mut v = path.as_bytes().to_vec();
            v.extend_from_slice(node.merkle_root.as_bytes());
            v
        })
        .collect();
    blake3_hex(&combined)
}

// ─── SnapshotManifest impl ────────────────────────────────────────────────────

impl SnapshotManifest {
    pub fn new(id: impl Into<String>, base_id: Option<String>) -> Self {
        let mut m = Self {
            id: id.into(),
            base_id,
            files: BTreeMap::new(),
            created_at: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_secs(),
            committed: false,
            manifest_root: String::new(),
        };
        m.rehash();
        m
    }

    /// Insert or overwrite a file entry and recompute roots.
    pub fn upsert_file(&mut self, path: impl Into<String>, chunks: Vec<ChunkRef>, mode: u32) {
        let total_size: u64 = chunks.iter().map(|c| c.size as u64).sum();
        let merkle_root = compute_file_merkle(&chunks);
        let mtime = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        self.files.insert(
            path.into(),
            FileNode { chunks, total_size, mtime, mode, merkle_root },
        );
        self.rehash();
    }

    /// Remove a file path from the manifest.
    pub fn remove_file(&mut self, path: &str) -> bool {
        let removed = self.files.remove(path).is_some();
        if removed {
            self.rehash();
        }
        removed
    }

    /// Get the ordered list of ChunkRefs for a path.
    pub fn resolve(&self, path: &str) -> Option<&[ChunkRef]> {
        self.files.get(path).map(|n| n.chunks.as_slice())
    }

    pub fn rehash(&mut self) {
        self.manifest_root = compute_manifest_root(&self.files);
    }

    // ─── Serialisation ────────────────────────────────────────────────────

    /// Write JSON fallback to `<base>/<id>.json`.
    pub fn write_json(&self, base_dir: &Path) -> Result<PathBuf> {
        let path = base_dir.join(format!("{}.json", self.id));
        let mut f = File::create(&path)
            .with_context(|| format!("create manifest JSON {:?}", path))?;
        f.write_all(serde_json::to_string_pretty(self)?.as_bytes())?;
        debug!("Manifest JSON written to {:?}", path);
        Ok(path)
    }

    /// Write binary (cbor-encoded) manifest to `<base>/<id>.bin`.
    /// We use serde_json for simplicity; swap for prost if protobuf is needed.
    pub fn write_binary(&self, base_dir: &Path) -> Result<PathBuf> {
        let path = base_dir.join(format!("{}.bin", self.id));
        let encoded = serde_json::to_vec(self)?; // replace with prost for proto
        let mut f = File::create(&path)
            .with_context(|| format!("create manifest binary {:?}", path))?;
        f.write_all(&encoded)?;
        debug!("Manifest binary written to {:?}", path);
        Ok(path)
    }

    /// Load from JSON.
    pub fn load_json(path: &Path) -> Result<Self> {
        let data = fs::read_to_string(path)
            .with_context(|| format!("read manifest JSON {:?}", path))?;
        Ok(serde_json::from_str(&data)?)
    }

    // ─── Atomic commit ────────────────────────────────────────────────────

    /// Atomically replace the live manifest using `renameat2(RENAME_EXCHANGE)`
    /// or a fallback rename on platforms that do not support the syscall.
    pub fn commit_atomic(&mut self, base_dir: &Path) -> Result<()> {
        if self.committed {
            return Ok(());
        }

        // Write new version to a temp path
        let tmp_path = base_dir.join(format!("{}.tmp.json", self.id));
        let live_path = base_dir.join(format!("{}.live.json", self.id));

        let mut f = File::create(&tmp_path)?;
        f.write_all(serde_json::to_string_pretty(self)?.as_bytes())?;
        f.sync_all()?;
        drop(f);

        // Attempt renameat2(RENAME_EXCHANGE) via libc
        #[cfg(target_os = "linux")]
        {
            use std::ffi::CString;
            use std::os::unix::ffi::OsStrExt;

            let old = CString::new(tmp_path.as_os_str().as_bytes())?;
            let new = CString::new(live_path.as_os_str().as_bytes())?;

            // RENAME_EXCHANGE = 2
            let ret = unsafe {
                libc::syscall(
                    libc::SYS_renameat2,
                    libc::AT_FDCWD,
                    old.as_ptr(),
                    libc::AT_FDCWD,
                    new.as_ptr(),
                    2u32, // RENAME_EXCHANGE
                )
            };

            if ret != 0 {
                // Fallback: simple rename
                fs::rename(&tmp_path, &live_path)
                    .context("fallback rename failed")?;
            }
        }

        #[cfg(not(target_os = "linux"))]
        {
            fs::rename(&tmp_path, &live_path).context("rename failed")?;
        }

        self.committed = true;
        info!(
            "Snapshot {} committed atomically (root={})",
            self.id, self.manifest_root
        );
        Ok(())
    }
}

// ─── FFI surface for Nim ─────────────────────────────────────────────────────

use std::ffi::{CStr, CString};
use std::os::raw::c_char;
use std::ptr;

/// Create a new manifest; returns an opaque heap pointer.
#[no_mangle]
pub extern "C" fn manifest_new(
    id: *const c_char,
    base_id: *const c_char,
) -> *mut SnapshotManifest {
    let id = unsafe { CStr::from_ptr(id).to_string_lossy().into_owned() };
    let base = if base_id.is_null() {
        None
    } else {
        Some(unsafe { CStr::from_ptr(base_id).to_string_lossy().into_owned() })
    };
    Box::into_raw(Box::new(SnapshotManifest::new(id, base)))
}

/// Free a manifest previously created by `manifest_new`.
#[no_mangle]
pub extern "C" fn manifest_free(m: *mut SnapshotManifest) {
    if !m.is_null() {
        unsafe { drop(Box::from_raw(m)) };
    }
}

/// Serialise manifest to a JSON string; caller must free with `manifest_free_str`.
#[no_mangle]
pub extern "C" fn manifest_to_json(m: *const SnapshotManifest) -> *mut c_char {
    let m = unsafe { &*m };
    let s = serde_json::to_string(m).unwrap_or_default();
    CString::new(s).map(|c| c.into_raw()).unwrap_or(ptr::null_mut())
}

/// Free a string returned by `manifest_to_json`.
#[no_mangle]
pub extern "C" fn manifest_free_str(s: *mut c_char) {
    if !s.is_null() {
        unsafe { drop(CString::from_raw(s)) };
    }
}

