//! NBD (Network Block Device) server
//!
//! Translates block read/write commands into Snapshot Engine
//! manifest-based chunk reads/writes, exposing virtual filesystems
//! to remote clients (Tier-2 "Margarine" hosts) over the network.
//!
//! Wire format: NBD fixed-newstyle protocol (RFC 10809)

const std = @import("std");
const net = std.net;
const mem = std.mem;
const assert = std.debug.assert;

// ─── NBD wire constants ───────────────────────────────────────────────────────

const NBD_MAGIC: u64 = 0x4e42444d41474943; // "NBDMAGIC"
const CLISERV_MAGIC: u64 = 0x00420281861253;
const IHAVEOPT: u64 = 0x49484156454F5054;
const REPLY_MAGIC: u64 = 0x3e889045565a9;

const NBD_OPT_EXPORT_NAME: u32 = 1;
const NBD_OPT_ABORT: u32 = 2;
const NBD_OPT_GO: u32 = 7;

const NBD_REP_ACK: u32 = 1;
const NBD_REP_SERVER: u32 = 2;
const NBD_REP_ERR_UNSUP: u32 = 0x8000_0001;

const NBD_CMD_READ: u16 = 0;
const NBD_CMD_WRITE: u16 = 1;
const NBD_CMD_DISC: u16 = 2;
const NBD_CMD_FLUSH: u16 = 3;

const NBD_FLAG_FIXED_NEWSTYLE: u16 = 1;
const NBD_FLAG_NO_ZEROES: u16 = 2;
const NBD_FLAG_HAS_FLAGS: u16 = 1;
const NBD_FLAG_READ_ONLY: u16 = 2;
const NBD_FLAG_SEND_FLUSH: u16 = 4;

const REQUEST_MAGIC: u32 = 0x25609513;

// ─── Chunk RPC stubs (replace with Nim IPC in production) ────────────────────

