// ─── NbdServer ────────────────────────────────────────────────────────────────

pub const NbdExportConfig = struct {
    snapshot_id: []const u8,
    export_name: []const u8 = "dev-platform",
    /// Virtual export size in bytes (e.g. 10 GiB for a workspace)
    export_size: u64 = 10 * 1024 * 1024 * 1024,
    read_only: bool = false,
};

pub const NbdServer = struct {
    allocator: mem.Allocator,
    config: NbdExportConfig,
    server: net.StreamServer,

    pub fn init(allocator: mem.Allocator, config: NbdExportConfig) NbdServer {
        return NbdServer{
            .allocator = allocator,
            .config = config,
            .server = net.StreamServer.init(.{ .reuse_address = true }),
        };
    }

    pub fn deinit(self: *NbdServer) void {
        self.server.deinit();
    }

    pub fn listen(self: *NbdServer, port: u16) !void {
        const addr = try net.Address.parseIp4("0.0.0.0", port);
        try self.server.listen(addr);
        std.log.info("NBD exporter listening on :{d}", .{port});

        while (true) {
            const conn = try self.server.accept();
            // Spawn a thread per connection
            const thread = try std.Thread.spawn(
                .{},
                handleConnection,
                .{ self.allocator, conn.stream, self.config },
            );
            thread.detach();
        }
    }
};

// ─── Per-connection handler ───────────────────────────────────────────────────

fn handleConnection(
    allocator: mem.Allocator,
    stream: net.Stream,
    config: NbdExportConfig,
) void {
    defer stream.close();

    doHandshake(allocator, stream, config) catch |err| {
        std.log.err("NBD handshake error: {}", .{err});
    };
}

fn doHandshake(
    allocator: mem.Allocator,
    stream: net.Stream,
    config: NbdExportConfig,
) !void {
    var w = stream.writer();
    var r = stream.reader();

    // ── Server initial greeting ──────────────────────────────────────────
    try w.writeIntBig(u64, NBD_MAGIC);
    try w.writeIntBig(u64, IHAVEOPT);
    try w.writeIntBig(u16, NBD_FLAG_FIXED_NEWSTYLE | NBD_FLAG_NO_ZEROES);

    // ── Client flags ─────────────────────────────────────────────────────
    const client_flags = try r.readIntBig(u32);
    _ = client_flags;

    // ── Option haggling ──────────────────────────────────────────────────
    while (true) {
        const opt_magic = try r.readIntBig(u64);
        if (opt_magic != IHAVEOPT) return error.BadMagic;

        const opt_id = try r.readIntBig(u32);
        const opt_len = try r.readIntBig(u32);

        var opt_data = try allocator.alloc(u8, opt_len);
        defer allocator.free(opt_data);
        _ = try r.readAll(opt_data);

        switch (opt_id) {
            NBD_OPT_GO, NBD_OPT_EXPORT_NAME => {
                // Acknowledge and send export info
                try w.writeIntBig(u64, REPLY_MAGIC);
                try w.writeIntBig(u32, opt_id);
                try w.writeIntBig(u32, NBD_REP_ACK);
                try w.writeIntBig(u32, 0); // data length

                // Export size + flags
                try w.writeIntBig(u64, config.export_size);
                var flags: u16 = NBD_FLAG_HAS_FLAGS | NBD_FLAG_SEND_FLUSH;
                if (config.read_only) flags |= NBD_FLAG_READ_ONLY;
                try w.writeIntBig(u16, flags);
                // 124 zero bytes padding (unless NO_ZEROES negotiated)
                if (client_flags & 1 == 0) {
                    const zeroes = [_]u8{0} ** 124;
                    try w.writeAll(&zeroes);
                }

                // Enter transmission phase
                return doTransmission(allocator, stream, config);
            },
            NBD_OPT_ABORT => {
                try w.writeIntBig(u64, REPLY_MAGIC);
                try w.writeIntBig(u32, NBD_OPT_ABORT);
                try w.writeIntBig(u32, NBD_REP_ACK);
                try w.writeIntBig(u32, 0);
                return;
            },
            else => {
                // Unsupported option
                try w.writeIntBig(u64, REPLY_MAGIC);
                try w.writeIntBig(u32, opt_id);
                try w.writeIntBig(u32, NBD_REP_ERR_UNSUP);
                try w.writeIntBig(u32, 0);
            },
        }
    }
}

fn doTransmission(
    allocator: mem.Allocator,
    stream: net.Stream,
    config: NbdExportConfig,
) !void {
    var w = stream.writer();
    var r = stream.reader();

    while (true) {
        // Read request header (28 bytes)
        const magic   = try r.readIntBig(u32);
        if (magic != REQUEST_MAGIC) return error.BadRequestMagic;

        const flags  = try r.readIntBig(u16);
        const cmd    = try r.readIntBig(u16);
        const handle = try r.readIntBig(u64);
        const offset = try r.readIntBig(u64);
        const length = try r.readIntBig(u32);

        _ = flags;

        switch (cmd) {
            NBD_CMD_READ => {
                const data = try snapshotRead(
                    allocator,
                    config.snapshot_id,
                    config.export_name,
                    offset,
                    length,
                );
                defer allocator.free(data);

                // Simple reply header
                try w.writeIntBig(u32, 0x67446698); // NBD_SIMPLE_REPLY_MAGIC
                try w.writeIntBig(u32, 0);            // error = 0 (success)
                try w.writeIntBig(u64, handle);
                try w.writeAll(data);
            },

            NBD_CMD_WRITE => {
                var payload = try allocator.alloc(u8, length);
                defer allocator.free(payload);
                _ = try r.readAll(payload);

                try snapshotWrite(
                    config.snapshot_id,
                    config.export_name,
                    offset,
                    payload,
                );

                try w.writeIntBig(u32, 0x67446698);
                try w.writeIntBig(u32, 0);
                try w.writeIntBig(u64, handle);
            },

            NBD_CMD_FLUSH => {
                // fsync stub
                try w.writeIntBig(u32, 0x67446698);
                try w.writeIntBig(u32, 0);
                try w.writeIntBig(u64, handle);
            },

            NBD_CMD_DISC => return,

            else => {
                std.log.warn("Unknown NBD command: {d}", .{cmd});
                try w.writeIntBig(u32, 0x67446698);
                try w.writeIntBig(u32, 22); // EINVAL
                try w.writeIntBig(u64, handle);
            },
        }
    }
}

// ─── Entry point ─────────────────────────────────────────────────────────────

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const snapshot_id_env = std.os.getenv("SNAPSHOT_ID") orelse "default";
    const port_str = std.os.getenv("NBD_PORT") orelse "10809";
    const port = try std.fmt.parseInt(u16, port_str, 10);

    var server = NbdServer.init(allocator, .{
        .snapshot_id = snapshot_id_env,
        .export_size = 10 * 1024 * 1024 * 1024, // 10 GiB default
    });
    defer server.deinit();

    try server.listen(port);
}

