```python
"""
Planner – wraps OpenAI calls and injects DTG guidance.
"""
from __future__ import annotations

import ctypes
import json
import os
from typing import Any, Dict, List

import openai
from opentelemetry import trace

from .utils import load_dtg_lib, guidance_name

tracer = trace.get_tracer(__name__)

OPENAI_MODEL   = os.getenv("OPENAI_MODEL", "gpt-4o")
MAX_CTX_TOKENS = 32_000

_dtg: ctypes.CDLL | None = load_dtg_lib()


def _call_openai(messages: List[Dict[str, str]]) -> str:
    """Thin wrapper around openai.chat.completions.create."""
    client = openai.OpenAI()
    completion = client.chat.completions.create(
        model=OPENAI_MODEL,
        messages=messages,
        temperature=0,
    )
    return completion.choices[0].message.content or ""


def _inject(prompt: str, guidance: int) -> str:
    """Inject DTG micro-instruction via Zig FFI if library is available."""
    if _dtg is None or guidance == 0:
        return prompt
    raw = _dtg.inject(prompt.encode(), ctypes.c_uint32(guidance))
    if raw is None:
        return prompt
    return raw.decode("utf-8", errors="replace")


def build_task_list(
    description: str,
    rag_context: str,
    dtg_guidance: int = 0,
) -> List[Dict[str, Any]]:
    """
    Call the LLM to decompose *description* into tasks.

    Parameters
    ----------
    description:   Natural-language request from the user.
    rag_context:   Source-code snippets from the RAG pipeline (≤ 32k tokens).
    dtg_guidance:  Encoded DTG enum value from the previous step.
    """
    with tracer.start_as_current_span("planner.build_task_list") as span:
        span.set_attribute("dtg_guidance", guidance_name(dtg_guidance))
        span.set_attribute("rag_chars",    len(rag_context))

        system_prompt = (
            "You are an expert software-development planner. "
            "Return ONLY a JSON array of task objects with keys: "
            "id (int), action (string), target (string), parameters (object). "
            "Actions: edit_code | run_build | run_tests | verify_ui."
        )

        user_prompt = f"""Task description:
{description}

Relevant source context (from RAG):
{rag_context[:MAX_CTX_TOKENS]}
"""
        user_prompt = _inject(user_prompt, dtg_guidance)

        messages = [
            {"role": "system", "content": system_prompt},
            {"role": "user",   "content": user_prompt},
        ]

        raw = _call_openai(messages)

        # Strip markdown fences if present
        clean = raw.strip().lstrip("```json").lstrip("```").rstrip("```")
        tasks: List[Dict[str, Any]] = json.loads(clean)

        span.set_attribute("task_count", len(tasks))
        return tasks
```

