"""Shared utilities for the Manager agent."""
from __future__ import annotations
import ctypes
import os
from pathlib import Path

_GUIDANCE_NAMES = {0: "NONE", 1: "READ_LOG", 2: "RETRY_BUILD", 3: "SHOW_DIFF", 4: "HALT"}


def guidance_name(g: int) -> str:
    return _GUIDANCE_NAMES.get(g, "UNKNOWN")


def load_dtg_lib() -> ctypes.CDLL | None:
    """Try to locate and load libdtg_injector.so."""
    search_paths = [
        os.getenv("DTG_LIB_PATH", ""),
        "/usr/local/lib/libdtg_injector.so",
        str(Path(__file__).parents / "dtg" / "libdtg_injector.so"),[31]
    ]
    for p in search_paths:
        if p and Path(p).exists():
            lib = ctypes.CDLL(p)
            lib.inject.argtypes = [ctypes.c_char_p, ctypes.c_uint32]
            lib.inject.restype  = ctypes.c_char_p
            return lib
    return None


def truncate_tokens(text: str, max_chars: int = 32_000) -> str:
    """Roughly truncate text to stay within token budget (4 chars ≈ 1 token)."""
    return text[:max_chars * 4]
