"""
Nix toolchain helper – loads env cache and runs nix build.
"""
from __future__ import annotations
import json
import os
import subprocess
import time
from pathlib import Path
from typing import Dict, Any

from opentelemetry import trace

tracer = trace.get_tracer(__name__)

CACHE_PATH = Path(os.getenv("NIX_ENV_CACHE", "/cache/replit/nix/env.json"))


def load_env_cache() -> Dict[str, Any] | None:
    """
    Load the Nix env cache and validate all store paths exist on disk.
    Returns None on cache miss (triggers a full nix evaluation).
    """
    if not CACHE_PATH.exists():
        return None

    try:
        data: Dict[str, Any] = json.loads(CACHE_PATH.read_text())
    except json.JSONDecodeError:
        return None

    paths = data.get("paths", [])
    for p in paths:
        if not Path(p).exists():
            return None          # ← cache miss

    return data


def write_env_cache(env_data: Dict[str, Any]) -> None:
    CACHE_PATH.parent.mkdir(parents=True, exist_ok=True)
    CACHE_PATH.write_text(json.dumps(env_data, indent=2))


def ensure_env(flake_ref: str = ".") -> Dict[str, Any]:
    """
    Return Nix env dict.  Hits the ≤50 ms cache when warm;
    falls back to `nix eval` + `nix-store --query --requisites` otherwise.
    """
    with tracer.start_as_current_span("toolchain.ensure_env") as span:
        t0 = time.perf_counter()

        cached = load_env_cache()
        if cached is not None:
            elapsed_ms = (time.perf_counter() - t0) * 1000
            span.set_attribute("cache_hit",  True)
            span.set_attribute("latency_ms", elapsed_ms)
            assert elapsed_ms <= 50, f"Cache hit took {elapsed_ms:.1f} ms (limit 50 ms)"
            return cached

        span.set_attribute("cache_hit", False)

        # Full evaluation
        result = subprocess.run(
            ["nix", "build", flake_ref, "--print-out-paths", "--no-link"],
            capture_output=True, text=True, check=True,
        )
        store_paths = result.stdout.strip().splitlines()

        # Collect all requisites
        req = subprocess.run(
            ["nix-store", "--query", "--requisites"] + store_paths,
            capture_output=True, text=True, check=True,
        )
        all_paths = sorted(set(req.stdout.strip().splitlines()))

        env_data = {
            "version": "1.0",
            "paths": all_paths,
            "env": {
                "PATH": os.environ.get("PATH", ""),
                "PYTHONPATH": os.environ.get("PYTHONPATH", ""),
                "LD_LIBRARY_PATH": os.environ.get("LD_LIBRARY_PATH", ""),
            },
        }
        write_env_cache(env_data)
        return env_data


def nix_build(snapshot_dir: str) -> Dict[str, Any]:
    """Run `nix build` inside snapshot directory; return structured result."""
    with tracer.start_as_current_span("toolchain.nix_build") as span:
        span.set_attribute("snapshot_dir", snapshot_dir)
        t0 = time.perf_counter()

        try:
            proc = subprocess.run(
                ["nix", "build", "--no-link", "--print-build-logs"],
                cwd=snapshot_dir,
                capture_output=True,
                text=True,
                timeout=300,
            )
            elapsed = (time.perf_counter() - t0) * 1000
            span.set_attribute("duration_ms", elapsed)
            span.set_attribute("exit_code",   proc.returncode)

            return {
                "success":   proc.returncode == 0,
                "stdout":    proc.stdout,
                "stderr":    proc.stderr,
                "logs":      proc.stdout + proc.stderr,
                "exit_code": proc.returncode,
            }

        except subprocess.TimeoutExpired:
            return {"success": False, "stderr": "Timeout (300 s)", "logs": "", "exit_code": -1}
        except FileNotFoundError:
            return {"success": False, "stderr": "nix not in PATH", "logs": "", "exit_code": -1}
```

### `agents/editor/editor/diff.py`

```python
"""
Unified-diff parser and applier.

Produces a structured patch list from an incoming diff string, then writes
each changed file into the target snapshot via the Snapshot Engine RPC.
"""
from __future__ import annotations

import json
import socket
from dataclasses import dataclass
from typing import List, Optional

import unidiff


@dataclass
class PatchFile:
    path: str
    hunks: List[str]


def parse_diff(diff_text: str) -> List[PatchFile]:
    """Parse unified-diff text into a list of PatchFile objects."""
    patch = unidiff.PatchSet(diff_text)
    result: List[PatchFile] = []

    for patched_file in patch:
        target = patched_file.path.lstrip("b/")
        hunks = [str(h) for h in patched_file]
        result.append(PatchFile(path=target, hunks=hunks))

    return result


def _rpc(host: str, port: int, method: str, params: dict) -> dict:
    """Synchronous JSON-RPC call to the Snapshot Engine."""
    req = json.dumps({"jsonrpc": "2.0", "method": method, "params": params, "id": 1})
    with socket.create_connection((host, port), timeout=10) as s:
        s.sendall((req + "\n").encode())
        buf = b""
        while True:
            chunk = s.recv(65536)
            if not chunk:
                break
            buf += chunk
            if b"\n" in chunk:
                break
    return json.loads(buf.decode())


def apply_diff_to_snapshot(
    diff_text: str,
    snapshot_id: str,
    rpc_host: str = "127.0.0.1",
    rpc_port: int = 9090,
) -> str:
    """
    Fork `snapshot_id`, apply the diff, commit, and return the new snapshot ID.
    """
    # 1. Fork
    fork_resp = _rpc(rpc_host, rpc_port, "fork", {"baseSnapshotId": snapshot_id})
    new_id: str = fork_resp["result"]

    # 2. Read existing content + apply hunks in memory
    patches = parse_diff(diff_text)
    for pf in patches:
        # Read current content from snapshot (may be empty if new file)
        try:
            read_resp = _rpc(rpc_host, rpc_port, "read", {"snapshotId": new_id, "path": pf.path})
            current = read_resp.get("result", "")
        except Exception:
            current = ""

        # Apply all hunks sequentially using unidiff line list
        patch = unidiff.PatchSet(diff_text)
        for pf2 in patch:
            if pf2.path.lstrip("b/") == pf.path:
                lines = current.splitlines(keepends=True)
                for hunk in pf2:
                    # Simple line-based apply (production would use Myers diff)
                    out_lines: List[str] = []
                    src_line = 0
                    for hunk_line in hunk:
                        if hunk_line.line_type == " ":
                            out_lines.append(lines[src_line] if src_line < len(lines) else "")
                            src_line += 1
                        elif hunk_line.line_type == "+":
                            out_lines.append(hunk_line.value)
                        elif hunk_line.line_type == "-":
                            src_line += 1
                    lines = out_lines
                current = "".join(lines)

        # Write updated content back
        _rpc(rpc_host, rpc_port, "write", {
            "snapshotId": new_id,
            "path": pf.path,
            "data": current,
        })

    # 3. Commit
    commit_resp = _rpc(rpc_host, rpc_port, "commit", {"snapshotId": new_id})
    return commit_resp["result"]
```

