"""
Playwright runner – headless browser test harness.
"""
from __future__ import annotations

import time
from typing import Any, Dict, List

from playwright.async_api import Page, async_playwright


async def run_smoke_tests(url: str) -> Dict[str, Any]:
    """
    Execute a smoke test suite against *url*.
    Returns a dict with keys: passed, errors, metrics.
    """
    errors: List[str] = []
    metrics: Dict[str, Any] = {}

    async with async_playwright() as pw:
        browser = await pw.chromium.launch(headless=True, args=["--no-sandbox"])
        ctx = await browser.new_context(viewport={"width": 1920, "height": 1080})
        page = await ctx.new_page()

        t0 = time.perf_counter()
        resp = await page.goto(url, wait_until="networkidle", timeout=30_000)
        metrics["load_ms"] = (time.perf_counter() - t0) * 1000
        metrics["status"]  = resp.status if resp else 0

        if not resp or resp.status >= 400:
            errors.append(f"HTTP {metrics['status']} loading {url}")
        else:
            # Title check
            title = await page.title()
            metrics["title"] = title

            # No JS console errors
            console_errors: List[str] = []
            page.on("console", lambda msg: console_errors.append(msg.text)
                    if msg.type == "error" else None)
            await page.wait_for_timeout(1000)
            if console_errors:
                errors.extend([f"console.error: {e}" for e in console_errors])

            # Accessibility: every image must have alt text
            imgs = await page.query_selector_all("img:not([alt])")
            if imgs:
                errors.append(f"{len(imgs)} image(s) missing alt attribute")

        await browser.close()

    return {"passed": len(errors) == 0, "errors": errors, "metrics": metrics}


async def run_suite(url: str, suite: str = "default") -> Dict[str, Any]:
    """Dispatch to the appropriate test suite."""
    if suite in ("default", "smoke"):
        return await run_smoke_tests(url)
    return {"passed": True, "errors": [], "metrics": {}}
