```python
"""
Potemkin detector – finds DOM elements that look interactive but aren't.
"""
from __future__ import annotations

import json
from typing import Any, Dict, List

from playwright.async_api import Page, async_playwright


# JavaScript injected into the browser to enumerate "decorative" elements
_SCAN_JS = """
() => {
    const issues = [];
    const interactive = document.querySelectorAll(
        'button, [role="button"], a, [role="link"], input, select, textarea'
    );
    for (const el of interactive) {
        const rect = el.getBoundingClientRect();
        if (rect.width === 0 || rect.height === 0) continue; // invisible – skip

        const listeners = (window.__getEventListeners && window.__getEventListeners(el)) || {};
        const hasClick  = typeof el.onclick === 'function'
                       || (listeners.click && listeners.click.length > 0)
                       || el.getAttribute('onclick')
                       || el.getAttribute('data-action');

        const tag  = el.tagName.toLowerCase();
        const isAnchor = tag === 'a';
        const href = el.getAttribute('href');
        const isFunctionalAnchor = isAnchor && href && href !== '#';

        if (!hasClick && !isFunctionalAnchor) {
            issues.push({
                tag:       tag,
                id:        el.id || null,
                classes:   el.className || null,
                innerText: (el.innerText || '').slice(0, 80),
                rect:      {x: rect.x, y: rect.y, w: rect.width, h: rect.height}
            });
        }
    }
    return issues;
}
"""


async def scan_url(url: str) -> List[Dict[str, Any]]:
    """
    Navigate to *url* and return a list of Potemkin element descriptors.
    """
    async with async_playwright() as pw:
        browser = await pw.chromium.launch(
            headless=True,
            args=["--no-sandbox", "--disable-dev-shm-usage"],
        )
        page: Page = await browser.new_page()

        # Inject Chrome DevTools Protocol hook for event-listener introspection
        await page.add_init_script("""
            (() => {
                const orig = EventTarget.prototype.addEventListener;
                EventTarget.prototype.addEventListener = function(type, fn, opts) {
                    this.__evtListeners = this.__evtListeners || {};
                    (this.__evtListeners[type] = this.__evtListeners[type] || []).push(fn);
                    return orig.call(this, type, fn, opts);
                };
                window.__getEventListeners = el => el.__evtListeners || {};
            })();
        """)

        await page.goto(url, wait_until="networkidle", timeout=30_000)

        raw = await page.evaluate(_SCAN_JS)
        issues: List[Dict[str, Any]] = json.loads(json.dumps(raw))  # normalise

        await browser.close()

    return issues


async def run(snapshot_url: str) -> Dict[str, Any]:
    issues = await scan_url(snapshot_url)
    return {"total": len(issues), "issues": issues, "passed": len(issues) == 0}
```

