"""
Embedder – wraps OpenAI text-embedding-ada-002 with GCS caching.
"""
from __future__ import annotations

import hashlib
import json
import os
from typing import List

import openai
from google.cloud import storage

OPENAI_API_KEY   = os.environ["OPENAI_API_KEY"]
GCS_BUCKET       = os.getenv("EMBEDDING_BUCKET", "dev-platform-embeddings")
EMBEDDING_MODEL  = "text-embedding-ada-002"
EMBEDDING_DIM    = 1536

openai.api_key = OPENAI_API_KEY
_gcs = storage.Client()
_bucket = _gcs.bucket(GCS_BUCKET)


def _cache_key(text: str) -> str:
    return hashlib.sha256(text.encode()).hexdigest()


def _load_from_cache(key: str) -> List[float] | None:
    blob = _bucket.blob(f"embeddings/{key}.json")
    if not blob.exists():
        return None
    data = json.loads(blob.download_as_text())
    return data["embedding"]


def _save_to_cache(key: str, embedding: List[float]) -> None:
    blob = _bucket.blob(f"embeddings/{key}.json")
    blob.upload_from_string(
        json.dumps({"embedding": embedding}),
        content_type="application/json",
    )


def embed(text: str) -> List[float]:
    """
    Return the embedding for *text*.
    Results are cached in GCS so that repeated calls cost zero API credits.
    """
    key = _cache_key(text)

    cached = _load_from_cache(key)
    if cached is not None:
        return cached

    response = openai.Embedding.create(input=text, model=EMBEDDING_MODEL)
    embedding: List[float] = response["data"]["embedding"]

    _save_to_cache(key, embedding)
    return embedding
