"""
Vector store – Pinecone client wrapper.
"""
from __future__ import annotations

import os
from typing import Any, Dict, List

from pinecone import Pinecone, ServerlessSpec

INDEX_NAME = "dev-platform-index"
NAMESPACE  = "source-code"

_pc    = Pinecone(api_key=os.environ["PINECONE_API_KEY"])

# Create index on first use if it doesn't exist
existing = [idx.name for idx in _pc.list_indexes()]
if INDEX_NAME not in existing:
    _pc.create_index(
        name=INDEX_NAME,
        dimension=1536,
        metric="cosine",
        spec=ServerlessSpec(cloud="gcp", region="us-west1"),
    )

_index = _pc.Index(INDEX_NAME)


def upsert(doc_id: str, embedding: List[float], metadata: Dict[str, Any] | None = None) -> None:
    """Insert or update a document embedding in the index."""
    _index.upsert(
        vectors=[{"id": doc_id, "values": embedding, "metadata": metadata or {}}],
        namespace=NAMESPACE,
    )


def query(embedding: List[float], top_k: int = 5) -> List[Dict[str, Any]]:
    """
    Return the *top_k* nearest documents.
    Each result has keys: id, score, metadata.
    """
    result = _index.query(
        vector=embedding,
        top_k=top_k,
        namespace=NAMESPACE,
        include_metadata=True,
    )
    return [
        {"id": m["id"], "score": m["score"], "metadata": m.get("metadata", {})}
        for m in result["matches"]
    ]


def delete(doc_id: str) -> None:
    _index.delete(ids=[doc_id], namespace=NAMESPACE)
