"""
Real-time presence WebSocket server.

Accepts connections from browsers and from the Editor Agent.
Broadcasts cursor positions, text selections, and CRDT ops
to every participant in the same workspace room.
"""
from __future__ import annotations

import asyncio
import json
from collections import defaultdict
from typing import Any, Dict, Set

from fastapi import FastAPI, WebSocket, WebSocketDisconnect
from opentelemetry import trace

tracer = trace.get_tracer(__name__)

app = FastAPI(title="Presence Service", version="0.1.0")

# room_id -> set of active websocket connections
_rooms: Dict[str, Set[WebSocket]] = defaultdict(set)


async def _broadcast(room: str, message: Dict[str, Any], exclude: WebSocket | None = None) -> None:
    dead: Set[WebSocket] = set()
    for ws in list(_rooms[room]):
        if ws is exclude:
            continue
        try:
            await ws.send_json(message)
        except Exception:
            dead.add(ws)
    _rooms[room] -= dead


@app.websocket("/ws/{room_id}")
async def websocket_endpoint(websocket: WebSocket, room_id: str):
    await websocket.accept()
    _rooms[room_id].add(websocket)

    with tracer.start_as_current_span("presence.connection") as span:
        span.set_attribute("room_id", room_id)
        span.set_attribute("participants", len(_rooms[room_id]))

    try:
        await _broadcast(
            room_id,
            {"type": "peer_joined", "count": len(_rooms[room_id])},
            exclude=websocket,
        )

        while True:
            raw = await websocket.receive_text()
            msg: Dict[str, Any] = json.loads(raw)
            msg_type = msg.get("type", "unknown")

            if msg_type in ("cursor", "selection", "crdt_op", "awareness"):
                await _broadcast(room_id, msg, exclude=websocket)

            elif msg_type == "ping":
                await websocket.send_json({"type": "pong"})

    except WebSocketDisconnect:
        _rooms[room_id].discard(websocket)
        await _broadcast(
            room_id,
            {"type": "peer_left", "count": len(_rooms[room_id])},
        )


@app.get("/rooms")
async def list_rooms():
    return {room: len(clients) for room, clients in _rooms.items()}


@app.get("/health")
async def health():
    return {"status": "healthy", "service": "presence"}
