```python
"""
Kafka Avro producer – forwards agent metric events to the metering topic.
"""
from __future__ import annotations

import asyncio
import os
import time
from typing import Any, Dict

import fastavro
import io
from aiokafka import AIOKafkaProducer

KAFKA_BOOTSTRAP = os.getenv("KAFKA_BOOTSTRAP", "localhost:9092")
KAFKA_TOPIC     = "agent-metrics"

# Avro schema
_SCHEMA = {
    "type": "record",
    "name": "AgentMetric",
    "namespace": "io.devplatform.metrics",
    "fields": [
        {"name": "task_id",      "type": "string"},
        {"name": "agent",        "type": {"type": "enum", "name": "Agent",
                                          "symbols": ["manager","editor","verifier","dtg","rag","snapshot"]}},
        {"name": "duration_ms",  "type": "long"},
        {"name": "cpu_ms",       "type": "long"},
        {"name": "memory_mb",    "type": "long"},
        {"name": "guidance",     "type": {"type": "enum", "name": "Guidance",
                                          "symbols": ["NONE","READ_LOG","RETRY_BUILD","SHOW_DIFF","HALT"]}},
        {"name": "timestamp_ms", "type": "long"},
    ],
}

_parsed_schema = fastavro.parse_schema(_SCHEMA)

_producer: AIOKafkaProducer | None = None


async def _get_producer() -> AIOKafkaProducer:
    global _producer
    if _producer is None:
        _producer = AIOKafkaProducer(bootstrap_servers=KAFKA_BOOTSTRAP)
        await _producer.start()
    return _producer


def _avro_encode(record: Dict[str, Any]) -> bytes:
    buf = io.BytesIO()
    fastavro.schemaless_writer(buf, _parsed_schema, record)
    return buf.getvalue()


async def send_metric(
    task_id: str,
    agent: str,
    duration_ms: int,
    cpu_ms: int,
    memory_mb: int,
    guidance: str = "NONE",
) -> None:
    record = {
        "task_id":      task_id,
        "agent":        agent,
        "duration_ms":  duration_ms,
        "cpu_ms":       cpu_ms,
        "memory_mb":    memory_mb,
        "guidance":     guidance,
        "timestamp_ms": int(time.time() * 1000),
    }
    payload = _avro_encode(record)
    producer = await _get_producer()
    await producer.send(KAFKA_TOPIC, value=payload, key=task_id.encode())


async def close() -> None:
    global _producer
    if _producer:
        await _producer.stop()
        _producer = None
```

### `observability/metering/clickhouse_client.py`

```python
"""
ClickHouse client – batch-inserts metrics from the Kafka consumer.
"""
from __future__ import annotations

import asyncio
import io
import os
import time
from typing import Any, Dict, List

import fastavro
from aiokafka import AIOKafkaConsumer
from clickhouse_driver import Client

KAFKA_BOOTSTRAP = os.getenv("KAFKA_BOOTSTRAP",   "localhost:9092")
KAFKA_TOPIC     = "agent-metrics"
KAFKA_GROUP     = "clickhouse-sink"
CH_HOST         = os.getenv("CLICKHOUSE_HOST",    "localhost")
CH_PORT         = int(os.getenv("CLICKHOUSE_PORT", "9000"))
CH_DATABASE     = os.getenv("CLICKHOUSE_DB",      "default")
BATCH_SIZE      = 500
FLUSH_INTERVAL  = 2.0   # seconds

_SCHEMA = {
    "type": "record",
    "name": "AgentMetric",
    "namespace": "io.devplatform.metrics",
    "fields": [
        {"name": "task_id",      "type": "string"},
        {"name": "agent",        "type": {"type": "enum", "name": "Agent",
                                          "symbols": ["manager","editor","verifier","dtg","rag","snapshot"]}},
        {"name": "duration_ms",  "type": "long"},
        {"name": "cpu_ms",       "type": "long"},
        {"name": "memory_mb",    "type": "long"},
        {"name": "guidance",     "type": {"type": "enum", "name": "Guidance",
                                          "symbols": ["NONE","READ_LOG","RETRY_BUILD","SHOW_DIFF","HALT"]}},
        {"name": "timestamp_ms", "type": "long"},
    ],
}
_parsed = fastavro.parse_schema(_SCHEMA)

_ch = Client(host=CH_HOST, port=CH_PORT, database=CH_DATABASE)

INSERT_SQL = """
INSERT INTO agent_metrics
  (timestamp, task_id, agent, duration_ms, cpu_ms, memory_mb, guidance)
VALUES
"""


def _decode(raw: bytes) -> Dict[str, Any]:
    return fastavro.schemaless_reader(io.BytesIO(raw), _parsed)


def _flush(rows: List[Dict[str, Any]]) -> None:
    if not rows:
        return

    from datetime import datetime
    data = [
        {
            "timestamp":   datetime.utcfromtimestamp(r["timestamp_ms"] / 1000),
            "task_id":     r["task_id"],
            "agent":       r["agent"],
            "duration_ms": r["duration_ms"],
            "cpu_ms":      r["cpu_ms"],
            "memory_mb":   r["memory_mb"],
            "guidance":    r["guidance"],
        }
        for r in rows
    ]
    _ch.execute(
        "INSERT INTO agent_metrics (timestamp,task_id,agent,duration_ms,cpu_ms,memory_mb,guidance) VALUES",
        data,
    )
    print(f"[ClickHouse] Inserted {len(data)} rows")


async def consume_loop() -> None:
    consumer = AIOKafkaConsumer(
        KAFKA_TOPIC,
        bootstrap_servers=KAFKA_BOOTSTRAP,
        group_id=KAFKA_GROUP,
        auto_offset_reset="earliest",
    )
    await consumer.start()

    batch: List[Dict[str, Any]] = []
    last_flush = time.monotonic()

    try:
        async for msg in consumer:
            batch.append(_decode(msg.value))

            now = time.monotonic()
            if len(batch) >= BATCH_SIZE or (now - last_flush) >= FLUSH_INTERVAL:
                _flush(batch)
                batch.clear()
                last_flush = now
    finally:
        if batch:
            _flush(batch)
        await consumer.stop()


if __name__ == "__main__":
    asyncio.run(consume_loop())
```

### `observability/otel/exporter.zig`

```zig
//! Zig OpenTelemetry exporter (OTLP/gRPC to Kafka bridge)
//!
//! Receives spans on a UNIX socket from other Zig processes,
//! serialises them as JSON, and forwards each batch to the
//! OpenTelemetry Collector's OTLP HTTP endpoint.

const std = @import("std");
const http = std.http;
const net  = std.net;
const mem  = std.mem;

const OTEL_ENDPOINT = "";
const BATCH_SIZE    = 128;
const FLUSH_MS      = 500;

pub const Span = struct {
    trace_id:   u8,   // hex[32]
    span_id:    u8,   // hex[33]
    name:       []const u8,
    start_us:   u64,
    end_us:     u64,
    service:    []const u8,
    attrs:      []const u8,  // JSON object string
};

fn spanToOtlpJson(span: Span, buf: *std.ArrayList(u8)) !void {
    const w = buf.writer();
    try w.print(
        \\{{"traceId":"{s}","spanId":"{s}","name":"{s}","startTimeUnixNano":{d},"endTimeUnixNano":{d},"attributes":{s}}}
    ,   .{
            span.trace_id,
            span.span_id,
            span.name,
            span.start_us  * 1000,
            span.end_us    * 1000,
            span.attrs,
        },
    );
}

fn flushBatch(allocator: mem.Allocator, spans: []const Span) !void {
    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();

    const w = body.writer();
    try w.writeAll(
        \\{"resourceSpans":[{"resource":{},"scopeSpans":[{"spans":[
    );

    for (spans, 0..) |span, i| {
        if (i > 0) try w.writeByte(',');
        try spanToOtlpJson(span, &body);
    }

    try w.writeAll("]}]}]}");

    // POST to OTel Collector
    var client = http.Client{ .allocator = allocator };
    defer client.deinit();

    var headers_buf: u8 = undefined;
    var req = try client.open(.POST, try std.Uri.parse(OTEL_ENDPOINT), .{
        .server_header_buffer = &headers_buf,
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = body.items.len };
    try req.send();
    try req.writeAll(body.items);
    try req.finish();
    try req.wait();

    std.log.info("Flushed {d} spans to OTel Collector", .{spans.len});
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Listen on UDP socket for span data from other processes
    const sock_path = "/tmp/otel-exporter.sock";
    std.fs.deleteFileAbsolute(sock_path) catch {};

    var server = try net.UnixStreamServer.init(sock_path, .{});
    defer server.deinit();

    std.log.info("OTel Zig exporter listening on {s}", .{sock_path});

    var pending = std.ArrayList(Span).init(allocator);
    defer pending.deinit();

    var last_flush = std.time.milliTimestamp();

    while (true) {
        // Non-blocking accept
        if (server.accept()) |conn| {
            defer conn.stream.close();

            var buf: u8 = undefined;
            const n = conn.stream.read(&buf) catch continue;
            if (n == 0) continue;

            // Expect one JSON span per connection
            const json_text = buf[0..n];
            const parsed = std.json.parseFromSlice(
                std.json.Value, allocator, json_text, .{}) catch continue;
            defer parsed.deinit();

            // Build Span from JSON
            const obj = parsed.value.object;
            const span = Span{
                .trace_id  = blk: {
                    var id: u8 = undefined;[32]
                    @memcpy(&id, (obj.get("trace_id") orelse continue).string[0..32]);
                    break :blk id;
                },
                .span_id   = blk: {
                    var id: u8 = undefined;[33]
                    @memcpy(&id, (obj.get("span_id") orelse continue).string[0..16]);
                    break :blk id;
                },
                .name      = (obj.get("name") orelse continue).string,
                .start_us  = @intCast((obj.get("start_us") orelse continue).integer),
                .end_us    = @intCast((obj.get("end_us")   orelse continue).integer),
                .service   = (obj.get("service") orelse continue).string,
                .attrs     = (obj.get("attrs")   orelse .{ .string = "{}" }).string,
            };

            try pending.append(span);
        } else |_| {}

        const now = std.time.milliTimestamp();
        if (pending.items.len >= BATCH_SIZE or
            (now - last_flush > FLUSH_MS and pending.items.len > 0))
        {
            flushBatch(allocator, pending.items) catch |err| {
                std.log.err("Flush failed: {}", .{err});
            };
            pending.clearRetainingCapacity();
            last_flush = now;
        }

        std.time.sleep(10 * std.time.ns_per_ms);
    }
}
```

