          name: https
        - containerPort: 80
          name: http
        env:
        - name: PORT_AUTHORITY_URL
          value: ""
        volumeMounts:
        - name: caddy-config
          mountPath: /etc/caddy
        - name: caddy-data
          mountPath: /data
        resources:
          limits:
            cpu:    "200m"
            memory: "128Mi"
      volumes:
      - name: caddy-config
        configMap:
          name: caddy-config
      - name: caddy-data
        emptyDir: {}
---
apiVersion: v1
kind: Service
metadata:
  name: networking-proxy
spec:
  selector:
    app: networking-proxy
  type: LoadBalancer
  ports:
  - name: https
    port: 443
    targetPort: 443
  - name: http
    port: 80
    targetPort: 80
