name: Integration Tests

on:
  push:
    branches: [ main, develop ]
  pull_request:
    branches: [ main ]

jobs:
  e2e-tests:
    runs-on: ubuntu-latest
    timeout-minutes: 45

    steps:
    - uses: actions/checkout@v4
      with:
        submodules: recursive

    - name: Install Nix
      uses: cachix/install-nix-action@v25
      with:
        nix_path: nixpkgs=channel:nixos-unstable

    - name: Cache Nix
      uses: cachix/cachix-action@v15
      with:
        name: dev-platform
        authToken: '${{ secrets.CACHIX_AUTH_TOKEN }}'

    - name: Install kind + kubectl
      run: |
        curl -Lo /usr/local/bin/kind \

        chmod +x /usr/local/bin/kind
        curl -Lo /usr/local/bin/kubectl \
          " -sL "
        chmod +x /usr/local/bin/kubectl

    - name: Create kind cluster
      run: |
        cat <<EOF | kind create cluster --config=-
        kind: Cluster
        apiVersion: kind.x-k8s.io/v1alpha4
        nodes:
          - role: control-plane
          - role: worker
          - role: worker
        EOF

    - name: Build platform images
      run: |
        nix build .#dev-platform
        # Load images into kind
        for svc in manager editor verifier dtg rag; do
          nix build .#$svc -o result-$svc
          kind load docker-image dev-platform/$svc:latest
        done

    - name: Apply Kubernetes manifests
      run: |
        kubectl apply -k infra/kubernetes
        kubectl wait --for=condition=Ready pod -l platform=dev-platform \
          --timeout=120s

    - name: Run E2E test suite
      run: bash ci/scripts/test_all.sh

    - name: Assert cache hit latency ≤ 50ms
      run: |
        nix-shell --run "python benchmark/env_cache_test.py"

    - name: Assert snapshot fork latency < 100ms
      run: |
        nix-shell --run "python benchmark/fork_latency_test.py"

    - name: Collect test artifacts
      if: always()
      uses: actions/upload-artifact@v4
      with:
        name: test-results
        path: |
          test-results/
          logs/

    - name: Teardown kind cluster
