      run:
        working-directory: infra/terraform

    steps:
    - uses: actions/checkout@v4

    - name: Authenticate to GCP
      uses: google-github-actions/auth@v2
      with:
        workload_identity_provider: ${{ secrets.GCP_WIF_PROVIDER }}
        service_account:            ${{ secrets.GCP_SA_EMAIL }}

    - name: Set up Terraform
      uses: hashicorp/setup-terraform@v3
      with:
        terraform_version: "1.10"

    - name: Terraform Init
      run: terraform init -backend-config="bucket=${{ secrets.TF_STATE_BUCKET }}"

    - name: Terraform Validate
      run: terraform validate

    - name: Terraform Plan
      run: |
        terraform plan -out=tfplan \
          -var="project_id=${{ secrets.GCP_PROJECT_ID }}" \
          -var="service_account_email=${{ secrets.GCP_SA_EMAIL }}"

    - name: Terraform Apply
      run: terraform apply -auto-approve tfplan

  build-and-push:
    name: Build & Push Container Images
    runs-on: ubuntu-latest
    needs: terraform

    steps:
    - uses: actions/checkout@v4

    - name: Install Nix
      uses: cachix/install-nix-action@v25

    - name: Authenticate to GCP
      uses: google-github-actions/auth@v2
      with:
        workload_identity_provider: ${{ secrets.GCP_WIF_PROVIDER }}
        service_account:            ${{ secrets.GCP_SA_EMAIL }}

    - name: Configure Docker for GCR
      run: gcloud auth configure-docker gcr.io

    - name: Build and tag images
      run: |
        TAG=${GITHUB_REF_NAME}
        for svc in manager editor verifier dtg rag; do
          nix build .#$svc -o out-$svc
          docker load < out-$svc
          docker tag dev-platform/$svc:latest \
            gcr.io/${{ secrets.GCP_PROJECT_ID }}/dev-platform/$svc:$TAG
          docker push gcr.io/${{ secrets.GCP_PROJECT_ID }}/dev-platform/$svc:$TAG
        done

  deploy-k8s:
    name: Deploy to GKE
    runs-on: ubuntu-latest
    needs: build-and-push

    steps:
    - uses: actions/checkout@v4

    - name: Authenticate to GCP
      uses: google-github-actions/auth@v2
      with:
        workload_identity_provider: ${{ secrets.GCP_WIF_PROVIDER }}
        service_account:            ${{ secrets.GCP_SA_EMAIL }}

    - name: Get GKE credentials
      run: |
        gcloud container clusters get-credentials dev-platform \
          --region ${{ secrets.GCP_REGION }} \
          --project ${{ secrets.GCP_PROJECT_ID }}

    - name: Update image tags in kustomization
      run: |
        cd infra/kubernetes
        TAG=${GITHUB_REF_NAME}
        # Update all image tags to the new version
        kustomize edit set image \
          dev-platform/manager=gcr.io/${{ secrets.GCP_PROJECT_ID }}/dev-platform/manager:$TAG \
          dev-platform/editor=gcr.io/${{ secrets.GCP_PROJECT_ID }}/dev-platform/editor:$TAG \
          dev-platform/verifier=gcr.io/${{ secrets.GCP_PROJECT_ID }}/dev-platform/verifier:$TAG \
          dev-platform/dtg=gcr.io/${{ secrets.GCP_PROJECT_ID }}/dev-platform/dtg:$TAG \
          dev-platform/rag=gcr.io/${{ secrets.GCP_PROJECT_ID }}/dev-platform/rag:$TAG

    - name: Apply Kubernetes manifests
      run: kubectl apply -k infra/kubernetes

    - name: Wait for rollout
      run: |
        for deploy in agent-manager agent-editor agent-verifier dtg-service rag-service; do
          kubectl rollout status deployment/$deploy \
            -n dev-platform --timeout=300s
        done

    - name: Health-check all services
      run: |
        SERVICES=(
          "agent-manager:8001"
          "agent-editor:8002"
          "agent-verifier:8003"
          "dtg-service:8006"
          "rag-service:8004"
        )
        for entry in "${SERVICES[@]}"; do
          svc="${entry%%:*}"
          port="${entry##*:}"
          STATUS=$(kubectl exec -n dev-platform deploy/$svc -- \
            curl -s -o /dev/null -w "%{http_code}" 
          if [ "$STATUS" != "200" ]; then
            echo "❌ $svc health check failed: HTTP $STATUS"
            exit 1
          fi
          echo "✅ $svc healthy"
        done
