#!/usr/bin/env bash
set -euo pipefail

echo "🔍 Linting dev-platform..."

# Zig format check
echo "  [Zig] Checking formatting..."
find . -name "*.zig" -not -path "*/zig-cache/*" | while read -r f; do
    zig fmt --check "$f" || { echo "❌ $f needs formatting"; exit 1; }
done
echo "  ✅ Zig OK"

# Nim style check
echo "  [Nim] Checking formatting..."
find . -name "*.nim" -not -path "*nimcache*" | while read -r f; do
    nimpretty --check "$f" || { echo "❌ $f needs nimpretty"; exit 1; }
done
echo "  ✅ Nim OK"

# Rust clippy
echo "  [Rust] Running clippy..."
for crate in cas snapshot; do
    (cd "$crate" && cargo clippy -- -D warnings) || { echo "❌ Rust $crate clippy failed"; exit 1; }
done
echo "  ✅ Rust OK"

# Python ruff
echo "  [Python] Running ruff..."
ruff check agents/ rag/ collaboration/presence/ observability/metering/ \
    || { echo "❌ Python lint failed"; exit 1; }
ruff format --check agents/ rag/ collaboration/presence/ observability/metering/
echo "  ✅ Python OK"

# Nix flake check
echo "  [Nix] Running flake check..."
nix flake check --no-build 2>&1 | grep -v "^trace:" || true
echo "  ✅ Nix OK"

# Terraform validate
echo "  [Terraform] Validating..."
(cd infra/terraform && terraform validate) || { echo "❌ Terraform invalid"; exit 1; }
echo "  ✅ Terraform OK"

