### `ci/scripts/release.sh`

```bash
#!/usr/bin/env bash
set -euo pipefail

VERSION="${1:-}"
if [ -z "$VERSION" ]; then
    echo "Usage: $0 <version>  (e.g. 0.2.0)"
    exit 1
fi

echo "🚀 Releasing dev-platform v$VERSION"

# Validate version format
if ! [[ "$VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
    echo "❌ Version must be semver (e.g. 1.2.3)"
    exit 1
fi

# Ensure working tree is clean
if [ -n "$(git status --porcelain)" ]; then
    echo "❌ Working tree is not clean – commit or stash changes first"
    exit 1
fi

# Run full test suite
echo "  Running tests..."
bash ci/scripts/test_all.sh

# Bump versions in pyproject.toml files
for f in agents/*/pyproject.toml rag/pyproject.toml collaboration/presence/pyproject.toml; do
    sed -i "s/^version = .*/version = \"$VERSION\"/" "$f"
done

# Bump Cargo.toml files
for f in cas/Cargo.toml snapshot/Cargo.toml; do
    sed -i "s/^version = .*/version = \"$VERSION\"/" "$f"
done

# Commit version bumps
git add -A
git commit -m "chore: bump version to $VERSION"

# Create annotated tag
git tag -a "v$VERSION" -m "Release v$VERSION"

echo "  Pushing tag..."
git push origin main
git push origin "v$VERSION"

echo ""
echo "✅ Released v$VERSION — GitHub Actions deploy workflow will trigger automatically."
```

