### `networking/proxy/entrypoint.sh`

```bash
#!/bin/sh
set -e

# Fetch the external port from Port Authority for this workspace
WORKSPACE_ID="${WORKSPACE_ID:-0}"
PORT_AUTHORITY_URL="${PORT_AUTHORITY_URL:-"

EXTERNAL_PORT=$(curl -sf -X POST "$PORT_AUTHORITY_URL/allocate" \
    -H "Content-Type: application/json" \
    -d "{\"workspace_id\": $WORKSPACE_ID}" \
    | grep -oE '"external_port":[0-9]+' | grep -oE '[0-9]+$')

if [ -z "$EXTERNAL_PORT" ]; then
    echo "❌ Failed to allocate external port from Port Authority"
    exit 1
fi

echo "✅ Allocated external port: $EXTERNAL_PORT"
export EXTERNAL_PORT

# Replace placeholder in Caddyfile
sed -i "s/__EXTERNAL_PORT__/$EXTERNAL_PORT/g" /etc/caddy/Caddyfile
sed -i "s/__WORKSPACE_ID__/$WORKSPACE_ID/g"   /etc/caddy/Caddyfile

exec /caddy run --config /etc/caddy/Caddyfile --adapter caddyfile
```

